"""Memory-field helpers for undeclared-fact discovery prompts."""

from __future__ import annotations

from typing import TYPE_CHECKING, Mapping

from rasa.mantle.memory.field import MemoryField

if TYPE_CHECKING:
    from rasa.mantle.memory.manager import MemoryManager
    from rasa.mantle.memory.schema import ProjectMemorySchema
    from rasa.mantle.skills.catalog import SkillCatalog

PROJECT_SKILL_ID = "project"
"""Scope id used for project-level memory fields in discovery prompts."""

_UNMAPPABLE_FIELD_TYPES = frozenset({"bool"})
"""Field types never offered as ``potential_mappings`` targets."""


def build_discovery_memory_fields(
    skill_catalog: "SkillCatalog",
    project_memory: "ProjectMemorySchema",
    *,
    observing_skill_id: str | None = None,
) -> dict[str, dict[str, MemoryField]]:
    """Return user-settable skill and project memory fields for discovery prompts.

    When *observing_skill_id* is ``None``, project fields are omitted.
    """
    memory_fields: dict[str, dict[str, MemoryField]] = {}
    for skill_id, skill in skill_catalog.skills.items():
        collect_owned = skill_catalog.collect_owned_entries.get(skill_id, frozenset())
        writable = {
            entry_name: field
            for entry_name, field in skill.memory.definition.all_fields().items()
            if _is_user_settable_field(entry_name, field, collect_owned=collect_owned)
        }
        if writable:
            memory_fields[skill_id] = writable

    if project_memory.fields and observing_skill_id is not None:
        project_collect_owned = _project_collect_owned_entries(
            skill_catalog, project_memory
        )
        project_writable = {
            entry_name: field
            for entry_name, field in project_memory.fields.items()
            if _is_user_settable_field(
                entry_name, field, collect_owned=project_collect_owned
            )
        }
        if project_writable:
            memory_fields[PROJECT_SKILL_ID] = project_writable

    return memory_fields


def filled_scoped_entries(
    memory: "MemoryManager",
    defined_memory_fields: Mapping[str, Mapping[str, MemoryField]],
    *,
    observing_skill_id: str | None = None,
    flow_id: str = "",
) -> set[str]:
    """Return scoped entries whose tracker slots currently hold a value.

    Each item uses ``{scope_id}.{entry_name}`` (e.g. ``card_replace.amount``,
    ``project.authenticated``) so same-named fields in different scopes do not
    collide in the discovery prompt. Uses :meth:`MemoryManager.read_all` so
    cross-skill public visibility is honoured.
    """
    if observing_skill_id is None:
        return set()

    readable = memory.read_all(observing_skill_id, flow_id)
    filled: set[str] = set()
    for scope_id, fields in defined_memory_fields.items():
        for entry_name in fields:
            slot_name = f"{scope_id}.{entry_name}"
            entry = readable.get(slot_name)
            if entry is not None and entry.value is not None:
                filled.add(slot_name)
    return filled


def known_discovered_fact_keys(memory: "MemoryManager") -> set[str]:
    """Return keys of every stored :class:`DiscoveredFact`."""
    return {fact.key for fact in memory.get_discovered_facts()}


def memory_entries_for_prompt(
    defined_memory_fields: Mapping[str, Mapping[str, MemoryField]],
) -> list[dict[str, str]]:
    """Flatten per-scope memory field maps into template-friendly rows."""
    rows: list[dict[str, str]] = []
    for skill_id, fields in defined_memory_fields.items():
        for entry_name, field in fields.items():
            if field.type in _UNMAPPABLE_FIELD_TYPES:
                continue
            rows.append(
                {
                    "skill_id": skill_id,
                    "entry": entry_name,
                    "description": field.description or "",
                }
            )
    return rows


def _project_collect_owned_entries(
    skill_catalog: "SkillCatalog",
    project_memory: "ProjectMemorySchema",
) -> frozenset[str]:
    """Return project fields collected by a skill flow's ``collect`` step."""
    project_field_names = project_memory.fields.keys()
    owned: set[str] = set()
    for entries in skill_catalog.collect_owned_entries.values():
        owned.update(entry for entry in entries if entry in project_field_names)
    return frozenset(owned)


def _is_user_provided_field(
    entry_name: str,
    field: MemoryField,
    *,
    collect_owned: frozenset[str],
) -> bool:
    """Return whether a field can hold a user-volunteered value."""
    return entry_name in collect_owned or field.llm_settable


def _is_user_settable_field(
    entry_name: str,
    field: MemoryField,
    *,
    collect_owned: frozenset[str],
) -> bool:
    """Return whether a memory field is user-settable for discovery.

    A field qualifies when it is user-provided (``llm_settable: true`` or owned
    by a ``collect`` step — the latter indexed at catalog load).
    """
    return _is_user_provided_field(entry_name, field, collect_owned=collect_owned)
